import { mapState } from "vuex";
import {
  productLabelCate,
  productLabelListApi,
  productLabelEdit,
  labelCateCreate,
  productLabel,
  productLabelShowApi,
  productLabelStatusApi,
  productLabelDeleteApi,
} from "@/api/product";
import uploadPictures from "@/components/uploadPictures";
export default {
  name: "product_label",
  data() {
    return {
      grid: {
        xl: 7,
        lg: 7,
        md: 12,
        sm: 24,
        xs: 24,
      },
      loading: false,
      columns1: [
        {
          type: "selection",
          width: 100,
          align: "center",
        },
        {
          title: "标签",
          slot: "label_name",
          width: 250,
        },
        {
          title: "是否开启",
          slot: "status",
          minWidth: 140,
          align: "center",
        },
        {
          title: "移动端展示",
          slot: "is_show",
          minWidth: 140,
          align: "center",
        },
        {
          title: "排序",
          key: "sort",
          minWidth: 100,
          align: "center",
        },
        {
          title: "创建时间",
          key: "add_time",
          minWidth: 150,
          align: "center",
        },
        {
          title: "操作",
          slot: "action",
          fixed: "right",
          minWidth: 120,
        },
      ],
      labelFrom: {
        page: 1,
        limit: 15,
        label_cate: "",
      },
      labelLists: [],
      total: 0,
      theme3: "light",
      labelSort: [],
      sortName: "",
      current: 0,

      modals: false,
      form: {
        id: 0,
        label_cate: "",
        label_name: "",
        style_type: 1, //样式类型 1自定义 2图片
        color: "#e93323",
        bg_color: "#fff",
        border_color: "#e93323",
        sort: 0,
        is_show: 1,
        icon: "",
        status: 1,
      },
      checkSelect: [],
      modalPic: false,
      rules: {
        name: [
          { required: true, message: "请输入热词名称", trigger: "blur" },
          { min: 2, max: 6, message: "长度在 2 到 6 个字符", trigger: "blur" },
        ],
        label_cate: [{ required: true, message: "请选择分组" }],
      },
      isEdit: false,
      ids: "",
    };
  },
  components: {
    uploadPictures,
  },
  computed: {
    ...mapState("admin/layout", ["isMobile"]),
    labelWidth() {
      return this.isMobile ? undefined : 75;
    },
    labelPosition() {
      return this.isMobile ? "top" : "right";
    },
  },
  created() {
    this.getproductLabelAll();
    this.getList();
  },
  methods: {
    // 添加
    add() {
      this.modals = true;
    },
    modalPicTap() {
      this.modalPic = true;
    },
    getPic(pic) {
      this.modalPic = false;
      this.form.icon = pic.att_dir;
    },
    delImage() {
      this.form.icon = "";
    },
    addWordsConfirm() {
      this.$refs.form.validate((valid) => {
        if (valid) {
          productLabel(this.form)
            .then((res) => {
              this.$Message.success(res.msg);
              this.modals = false;
              this.cancel();
              this.labelFrom.page = 1;
              this.getList();
            })
            .catch((res) => {
              this.$Message.error(res.msg);
            });
        }
      });
    },
    cancel() {
      this.form = {
        id: 0,
        label_cate: "",
        label_name: "",
        style_type: 1, //样式类型 1自定义 2图片
        color: "#e93323",
        bg_color: "#ffffff",
        border_color: "#e93323",
        sort: 0,
        is_show: 1,
        icon: "",
        status: 1,
      };
      this.isEdit = false;
    },
    // 分组列表
    getList() {
      this.loading = true;
      productLabelListApi(this.labelFrom)
        .then(async (res) => {
          let data = res.data;
          this.labelLists = data.list;
          this.total = data.count;
          this.loading = false;
        })
        .catch((res) => {
          this.loading = false;
          this.$Message.error(res.msg);
        });
    },
    pageChange(index) {
      this.labelFrom.page = index;
      this.getList();
    },
    // 全选
    onSelectTab(selection) {
      if (selection.length) {
        let data = [];
        selection.forEach((item) => {
          data.push(item.id);
        });
        this.ids = data.join(",");
      } else {
        this.ids = "";
      }
    },
    labelDel() {
      let data = {
        ids: this.ids,
        all: 0,
        where: this.labelFrom.label_cate,
      };
      this.$Modal.confirm({
        title: "提示",
        content: "<p>确定要删除吗？</p><p>删除后将无法恢复，请谨慎操作！</p>",
        onOk: () => {
          productLabelDeleteApi(data)
            .then((res) => {
              this.$Message.success(res.msg);
              this.labelFrom.page = 1;
              this.getList();
            })
            .catch((res) => {
              this.$Message.error(res.msg);
            });
        },
      });
    },
    showChange(row) {
      productLabelShowApi({ id: row.id, is_show: row.is_show })
        .then((res) => {
          this.$Message.success(res.msg);
        })
        .catch((res) => {
          this.$Message.error(res.msg);
        });
    },
    statusChange(row) {
      productLabelStatusApi({ id: row.id, status: row.status })
        .then((res) => {
          this.$Message.success(res.msg);
        })
        .catch((res) => {
          this.$Message.error(res.msg);
        });
    },
    // 修改
    edit(row) {
      let formObj = {
        id: row.id,
        label_cate: row.label_cate,
        label_name: row.label_name,
        style_type: row.style_type, //样式类型 1自定义 2图片
        color: row.color,
        bg_color: row.bg_color,
        border_color: row.border_color,
        sort: row.sort,
        is_show: row.is_show,
        icon: row.icon,
        status: row.status,
      };
      this.form = formObj;
      this.modals = true;
    },
    // 删除
    delLabel(row, tit, num) {
      console.log(row, num);
      let delfromData = {
        title: tit,
        num: num,
        url: `product/label/${row.id}`,
        method: "DELETE",
        ids: "",
      };
      this.$modalSure(delfromData)
        .then((res) => {
          this.$Message.success(res.msg);
          this.labelLists.splice(num, 1);
          this.getList();
        })
        .catch((res) => {
          this.$Message.error(res.msg);
        });
    },
    // 标签分类
    getproductLabelAll(key) {
      productLabelCate().then((res) => {
        let obj = {
          name: "全部",
          id: "",
        };
        res.data.list.unshift(obj);
        res.data.list.map((el) => {
          this.$set(el, "status", false);
        });
        this.labelSort = res.data.list;
        // if (!key) {
        //   this.sortName = res.data[0].id;
        //   this.labelFrom.label_cate = res.data[0].id;
        //   this.getList();
        // }
        // this.labelSort = res.data;
      });
    },
    // 显示标签小菜单
    showMenu(item) {
      this.labelSort.forEach((el) => {
        if (el.id == item.id) {
          el.status = item.status ? false : true;
        } else {
          el.status = false;
        }
      });
    },
    //编辑标签
    labelEdit(item) {
      this.$modalForm(productLabelEdit(item.id)).then(() =>
        this.getproductLabelAll()
      );
    },
    // 添加分类
    addSort() {
      this.$modalForm(labelCateCreate()).then(() => this.getproductLabelAll());
    },
    deleteSort(row, tit, num) {
      let delfromData = {
        title: tit,
        num: num,
        url: `product/label_cate/${row.id}`,
        method: "DELETE",
        ids: "",
      };
      this.$modalSure(delfromData)
        .then((res) => {
          this.$Message.success(res.msg);
          this.labelSort.splice(num, 1);
          this.labelSort = [];
          this.getproductLabelAll();
        })
        .catch((res) => {
          this.$Message.error(res.msg);
        });
    },
    bindMenuItem(name, index) {
      this.current = index;
      this.labelSort.forEach((el) => {
        el.status = false;
      });
      this.labelFrom.label_cate = name.id;
      this.getList();
    },
    synLabel() {},
  },
};
